Given an array arr[], where each element represents either a policeman (P) or a thief (T). Each policeman can catch only one thief and policeman can only catch a thief if the distance between them is at most k units. Find the maximum number of thieves that can be caught.Examples: Input: arr[] = ['P', 'T', 'T', 'P', 'T'], k = 1 Output: 2.Explanation: policeman of 0th index catches thief  at index 1 and policeman of 3rd index can catch thief at either 2nd or 4th index.Input: arr[] = ['T', 'T', 'P'], k = 1Output: 1Explanation: Policeman of 2th index catches thief  at index 1.Try It YourselfTable of Content[Naive Approach] Using Nested loops - O(n*k) Time and O(n) Space[Better Approach] Using Queue - O(n) Time and O(n) Space[Expected Approach] Using Two Pointers - O(n) Time and O(1) Space[Naive Approach] Using Nested loops - O(n*k) Time and O(n) SpaceThe idea is that for every policeman, we search for a thief within a range of 2*k + 1 in a sequential manner. If a thief is found, we mark index into the caught array to ensure that the same thief is not caught multiple times.
            C++

    #include <iostream>
#include<vector>
using namespace std;

int catchThieves(vector<char> &arr, int k) {
    int n = arr.size();

    // To mark if a thief is caught
    vector<bool> caught(n, false); 

    int count = 0; 
    for (int i = 0; i < n; ++i) {
        if (arr[i] == 'P') { 
            int start = max(0, i - k); 
            int end = min(n - 1, i + k); 

            // Search for an uncaught thief within range
            for (int j = start; j <= end; ++j) {
                if (arr[j] == 'T' && !caught[j]) { 
                    caught[j] = true; 
                    count++; 
                    break; 
                }
            }
        }
    }
    return count; 
}

int main() {
    int k = 1;
    vector<char> arr = { 'P', 'T', 'T', 'P', 'T' };
    cout<< catchThieves(arr, k) << endl;
}


