    #include <iostream>
#include<vector>
using namespace std;

int catchThieves(vector<char> &arr, int k) {
    int n = arr.size();

    int i = 0, j = 0; 
    int count = 0;

    while (i < n && j < n) {

        // Move i to the next policeman
        while (i < n && arr[i] != 'P') i++;

        // Move j to the next thief
        while (j < n && arr[j] != 'T') j++;

        // If both policeman and thief exist and are within range k
        if (i < n && j < n && abs(i - j) <= k) {

            count++; 

            i++; 

            j++; 
        } 
        else if (j < n && j < i) {
            j++;
        } 

        else if (i < n && i < j) {
            i++;
        }
    }
    return count;
}

